 var root=Path.Combine(Environment.GetEnvironmentVariable("PHOTOTRAIL_TEST_OUTPUT")!,"photo-gpx-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);Environment.SetEnvironmentVariable("PHOTOTRAIL_INPLACE_HISTORY",Path.Combine(root,"history"));Environment.SetEnvironmentVariable("PHOTOTRAIL_RENAME_COUNTERS",Path.Combine(root,"counters.json"));
