 PhotoDocument a=Doc("a&apost'.jpg"),b=Doc("b.jpg","2026:10:15 00:05:00Z"),c=Doc("c.jpg","2026:10:15 00:10:00.0000001Z"),duplicate=Doc("duplicate.jpg"),missing=Doc("missing.jpg",null),wall=Doc("wall.jpg","2026:10:15 00:00:00"),nano=Doc("nano.jpg","2026:10:15 00:00:00.123456789Z"),unknown=Doc("unknown.jpg",datum:null),noGps=Doc("nogps.jpg",gps:false),badGps=Doc("badgps.jpg",lon:181),historical=Doc("historical.jpg","0001:01:01 00:00:00Z");
 wall.SetSessionZone("UTC");a.SetDraft(PhotoDocument.PositionChanges(new(120,30),-5,"MANUAL"));var docs=new[]{c,a,b,duplicate,missing,wall,nano,unknown,noGps,badGps,historical};var plan=await PhotoGpxPlan.CreateAsync(docs);Check(plan.Count==5&&plan.Data.Segments.Count==2,"300-second strict boundary 100ns retained");Check(plan.Data.Segments[0].Count==4,"duplicate same-time/coordinate kept");Check(plan.Names.Take(2).SequenceEqual(new[]{"a&apost'.jpg","duplicate.jpg"}),"stable ties input order");Check(plan.Data.Segments[0][0].Elevation==-5,"negative known elevation");foreach(var reason in new[]{"缺主时间","精度不足","未知基准","缺GPS","非法GPS","平台范围不足"})Check(plan.Rows.Any(r=>r.Reason.Contains(reason)),"separate skip reason "+reason);
 Check(plan.Rows.Single(r=>r.Path==wall.FilePath).Point?.Time==plan.Rows.Single(r=>r.Path==b.FilePath).Point?.Time?.AddMinutes(-5),"wall clock uses explicit session UTC");var split=await PhotoGpxPlan.CreateAsync([a,b,c],299);Check(split.Data.Segments.Count==3,"custom gap");await Reject(()=>PhotoGpxPlan.CreateAsync([a],-1),"negative gap");await Reject(()=>PhotoGpxPlan.CreateAsync([a],0.00000001m),"unrepresentable threshold no rounding");
