 var cleared=Doc("clear.jpg");cleared.SetDraft(new Dictionary<string,string>{{"Composite:SubSecDateTimeOriginal",""}});var empty=await PhotoGpxPlan.CreateAsync([cleared]);Check(empty.Count==0&&empty.Rows.Single().Reason.Contains("缺主时间"),"main clear never falls back old XMP");await Reject(()=>empty.ExportAsync([cleared],Path.Combine(root,"empty.gpx"),"empty"),"all skipped no empty success");Check(!File.Exists(Path.Combine(root,"empty.gpx")),"empty target absent");
 var fresh=await PhotoGpxPlan.CreateAsync([b]);b.SetDraft(new Dictionary<string,string>{{"XMP-dc:Title","changed"}});await Reject(()=>fresh.ExportAsync([b],Path.Combine(root,"stale.gpx"),"stale"),"draft changed refused");b.ClearDraft();fresh=await PhotoGpxPlan.CreateAsync([b]);var t=File.GetLastWriteTimeUtc(b.FilePath);File.SetLastWriteTimeUtc(b.FilePath,t.AddSeconds(1));await Reject(()=>fresh.ExportAsync([b],Path.Combine(root,"system.gpx"),"stale"),"sameSHA System source changed refused");File.SetLastWriteTimeUtc(b.FilePath,t);using(var cancel=new CancellationTokenSource()){cancel.Cancel();await Reject(()=>PhotoGpxPlan.CreateAsync([b],300,cancel.Token),"cancel no generation");}
 var perf=new List<object>();var hundred=Enumerable.Range(0,100).Select(i=>Doc($"scale-{i:D3}.jpg",$"2026:10:15 00:{i/60:D2}:{i%60:D2}Z")).ToArray();foreach(var count in new[]{1,20,100}){var watch=Stopwatch.StartNew();var p=await PhotoGpxPlan.CreateAsync(hundred.Take(count).ToArray());Check(p.Count==count,"full photo count "+count);perf.Add(new{count,generateMs=watch.Elapsed.TotalMilliseconds,segments=p.Data.Segments.Count});}File.WriteAllText(Path.Combine(root,"performance.local.json"),JsonSerializer.Serialize(perf));
 var workspace=Path.Combine(root,"workspace.json");var state=TrackWorkspace.Read(workspace);Check(!File.Exists(workspace),"workspace missing readonly");state=await TrackWorkspace.SaveAsync(workspace,state,new(1,[new(target,false)],target));var stale=state;state=await TrackWorkspace.SaveAsync(workspace,state,state.State with{Entries=[new(target,true)]});await Reject(()=>TrackWorkspace.SaveAsync(workspace,stale,stale.State),"workspace stale instance refused");using(var gate=new FileStream(workspace+".guard",FileMode.Open,FileAccess.ReadWrite,FileShare.None))await Reject(()=>TrackWorkspace.SaveAsync(workspace,state,state.State),"workspace crosssession lock refused");Check(TrackWorkspace.Read(workspace).State.Selected==target&&TrackWorkspace.Read(workspace).State.Entries.Single().Visible,"workspace order visibility selected restart");File.WriteAllText(workspace,"invalid");await Reject(()=>TrackWorkspace.SaveAsync(workspace,state,state.State),"corrupt workspace no overwrite");Check(File.ReadAllText(workspace)=="invalid","corrupt bytes intact");
 var cache=Path.Combine(root,"snapshots.json");var snap=await TrackSnapshots.ReadSourceAsync(target);await TrackSnapshots.SaveAsync(cache,snap,snap);Check(TrackSnapshots.Read(cache).Length==1,"baseline reuses existing verified cache");using(var gate=new FileStream(cache+".guard",FileMode.Open,FileAccess.ReadWrite,FileShare.None))await Reject(()=>TrackSnapshots.SaveAsync(cache,snap,snap),"cache crosssession lock refused");var cached=TrackSnapshots.Read(cache).Single();File.Move(target,target+".away");await Reject(()=>TrackSnapshots.EnsureSourceAsync(cached),"missing cached source not matchable");await TrackAdjustment.ExportAsync(cached.Data,cached.Path,Path.Combine(root,"cached-copy.gpx"));Check(TrackAdjustment.Equal(cached.Data,TrackReader.ReadGpx(Path.Combine(root,"cached-copy.gpx"))),"verified missing-source cache export allowed");File.Move(target+".away",target);
